INSERT INTO `tbl_course` (`Course_ID`, `User_ID`, `Course_Name`, `Details`, `Duration`, `Is_Archived`, `Archived_At`) VALUES
(1, 1, 'PSBRC', 'The Public Safety Basic Recruit Course (PSBRC) is a mandatory, 6-month intensive pre-service training program for newly appointed police non-commissioned officers (like Patrolmen). Administered by the Philippine Public Safety College (PPSC) through the National Police Training Institute (NPTI), it transitions recruits from a civilian mindset to a regimented, highly disciplined police service.', '6 months', 0, NULL),
(2, 1, 'PSJLC', 'The Public Safety Junior Leadership Course (PSJLC) is a mandatory 10 to 11-week career program for junior Police Non-Commissioned Officers (PNCOs) in the Philippine National Police (PNP). It is designed to equip officers with the fundamental management, leadership, and operational skills required to handle junior key positions and team-building assignments.', '3 months', 0, NULL),
(5, 1, 'PSOCC', 'The Public Safety Officers Candidate Course (PSOCC) is a mandatory 14-week career training program for Police Non-Commissioned Officers (PNCOs) within the Philippine National Police (PNP) who are aspiring for promotion to the rank of Police Inspector. Administered by the Philippine Public Safety College (PPSC), the course is designed to equip junior officers with the fundamental leadership skills, specialized operational knowledge, and values necessary for higher management and team-building responsibilities.', '6 months', 0, NULL),
(8, 1, 'PSSLC', 'The Public Safety Senior Leadership Course (PSSLC) is a mandatory 3.5-month career course for senior non-commissioned officers (SPO3 to SPO4) in the Philippine National Police (PNP). It equips officers with the management and leadership capabilities required for assuming mid-level supervisory and administrative responsibilities.', '6 months', 0, NULL);
